/* Aplicativo local: interface em português, SQLite no Android e dados privados. */
'use strict';
const L=window.DoceLogic, $=selector=>document.querySelector(selector), E=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const copy=value=>JSON.parse(JSON.stringify(value)), uid=()=>globalThis.crypto?.randomUUID?.()||Date.now().toString(36)+Math.random().toString(36).slice(2);
let mode='real',state,route='home',entity='',draft=null,builder=null,editingLine=-1,formPhotos={},filter='',productCategory='Todas',orderFilter='Todos',customerFilter='Ativos',page=1,activeDay=L.today(),activeMonth=L.today().slice(0,7),confirmAction=null,pendingBackup=null,postalRequests=new Map();
const app=$('#app'),modal=$('#modal');
function blank(){return {schema:1,settings:{...copy(L.reminderDefaults),name:'Minha Confeitaria',phone:'',document:'',address:'',logo:'',change_days:3},products:copy(DOCE_SEED.products).map(p=>{delete p.demo_cents;return p;}),images:copy(DOCE_SEED.images),customers:[],inventory:[],quotes:[]};}
function demo(){
 const s=blank();s.settings.name='Doce Ateliê · Demonstração';s.products.forEach(p=>p.price_cents=DOCE_SEED.products.find(t=>t.id===p.id).demo_cents);
 ['Ana Beatriz','Beatriz Almeida','Camila Santos','Daniela Oliveira','Elisa Martins','Fernanda Costa'].forEach((name,i)=>s.customers.push({id:'c-demo-'+i,name,phone:'9299999000'+i,email:name.split(' ')[0].toLowerCase()+'@example.com',cpf:'',street:'Rua das Flores',number:String(120+i),neighborhood:'Centro',city:'Manaus',state:'AM',postal_code:'69005040',complement:'',address_reference:'',notes:'Cadastro fictício de demonstração.',photo:'cliente-'+i,active:true}));
 s.customers.forEach((c,i)=>{const product=s.products.find(p=>p.name===(i%2?'Bolo Especial':'Bolo Simples')),line=L.line(product,{quantity:2,fillings:[i%2?'Nutella':'Ninho'],reference_photo:product.photos[0]});const q={id:'q-demo-'+i,number:i+1,customer_id:c.id,customer:copy(c),shop:copy(s.settings),created_at:L.today(),valid_until:L.plusDays(L.today(),7),event_date:L.plusDays(L.today(),i+1),event_time:'14:00',fulfillment:'Retirada',delivery_address:'',lines:[line],payment_method:'PIX',pix_enabled:false,pix_percent:0,discount_cents:0,delivery_cents:0,notes:'Pedido fictício.',production_notes:'Conferir as cores antes de produzir.',payments:[],delivered:false};q.totals=L.totals(q.lines,q);if(i%2)q.payments.push({amount_cents:q.totals.deposit_cents,method:'PIX',note:'Sinal de exemplo',received_at:new Date().toISOString()});s.quotes.push(q);});return s;
}
function load(){const raw=window.Android?Android.loadState(mode):localStorage.getItem('doce-android-'+mode);state=raw?JSON.parse(raw):null;if(state?.storageError)throw Error('Não foi possível abrir os dados. Preserve o aplicativo e tente novamente antes de reinstalar.');if(!state){state=mode==='demo'?demo():blank();persist(state);}state.settings={...copy(L.reminderDefaults),...state.settings};const saved=localStorage.getItem('doce-draft-'+mode);draft=saved?JSON.parse(saved):null;}
function persist(value){const raw=JSON.stringify(value);if(window.Android){const error=Android.saveState(mode,raw);if(error)throw Error(error);}else localStorage.setItem('doce-android-'+mode,raw);}
function commit(fn){const next=copy(state);fn(next);persist(next);state=next;}
function saveDraft(){if(draft)localStorage.setItem('doce-draft-'+mode,JSON.stringify(draft));else localStorage.removeItem('doce-draft-'+mode);}
function toast(text){const box=$('#toast');box.textContent=text;box.hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>box.hidden=true,4000);}
function error(text,form){const box=form?.querySelector('.form-error');if(box){box.textContent=text;box.hidden=false;box.scrollIntoView({block:'center',behavior:'smooth'});}else toast(text);}
function heading(label,title,text=''){return `<div class="eyebrow">${E(label)}</div><h1>${E(title)}</h1>${text?`<p class="subtitle">${E(text)}</p>`:''}`;}
function button(label,action,id='',kind=''){return `<button type="button" class="${kind}" data-action="${action}" data-id="${E(id)}">${E(label)}</button>`;}
function image(id,reference=false){const src=state.images[id];return `<div class="image-frame${reference?' reference':''}">${src?`<img src="${E(src)}" alt="${reference?'Imagem de inspiração':'Foto do produto'}">`:'🧁'}</div>`;}
function field(label,name,value='',type='text',attrs=''){return `<label for="f_${E(name)}">${E(label)}</label><input id="f_${E(name)}" name="${E(name)}" type="${type}" value="${E(value)}" ${attrs}>`;}
function area(label,name,value='',attrs=''){return `<label for="f_${E(name)}">${E(label)}</label><textarea id="f_${E(name)}" name="${E(name)}" ${attrs}>${E(value)}</textarea>`;}
function select(label,name,options,value='',attrs=''){return `<label for="f_${E(name)}">${E(label)}</label><select id="f_${E(name)}" name="${E(name)}" ${attrs}>${options.map(option=>{const [v,text]=Array.isArray(option)?option:[option,option];return `<option value="${E(v)}" ${v===value?'selected':''}>${E(text)}</option>`;}).join('')}</select>`;}
function check(label,name,checked=false,value='1',attrs=''){return `<label class="check"><input type="checkbox" name="${E(name)}" value="${E(value)}" ${checked?'checked':''} ${attrs}>${E(label)}</label>`;}
function formError(){return '<div class="error form-error" hidden role="alert"></div>';}
function metric(label,value){return `<div class="metric"><small>${E(label)}</small><strong>${E(value)}</strong></div>`;}
function empty(title,text){return `<div class="empty">✦<strong>${E(title)}</strong><p>${E(text)}</p></div>`;}
function dateLabel(value,time=''){return value?value.split('-').reverse().join('/')+(time?' · '+time:''):'—';}
function statusBadge(q){const status=L.status(q);return `<span class="badge ${status==='Em Aberto'||status==='Vencido'?'coral':''}">${E(status)}</span>`;}
function avatar(c){return state.images[c.photo]?`<img class="avatar" src="${E(state.images[c.photo])}" alt="Foto de ${E(c.name)}">`:`<span class="avatar">${E(c.name.split(' ').slice(0,2).map(x=>x[0]).join(''))}</span>`;}
function photoInput(label,key,multiple=false){return `<label>${E(label)}</label><input type="file" accept="image/jpeg,image/png,image/webp" data-photo="${key}"><p class="hint">JPG, PNG ou WEBP · até 10 MB. As imagens se ajustam ao quadro padrão.${multiple?' Até três fotos; adicione uma por vez.':''}</p><div class="photo-list" id="photos_${key}">${photoPreview(key,multiple)}</div>`;}
function photoPreview(key,multiple=false){const ids=multiple?(formPhotos[key]||[]):[formPhotos[key]].filter(Boolean);return ids.map((id,i)=>`<div><img src="${E(state.images[id])}" alt="Imagem selecionada">${button('Remover','remove-photo',key+':'+i,'small')}</div>`).join('');}
function formShell(kind,content){return `<form data-form="${kind}">${content}${formError()}<div class="toolbar"><button class="primary" type="submit">Salvar ${kind==='customer'?'cliente':kind==='product'?'produto':kind==='inventory'?'insumo':'configurações'}</button>${button('Cancelar','cancel-form')}</div></form>`;}
function go(next,id=''){route=next;entity=id;filter='';page=1;formPhotos={};render();window.scrollTo(0,0);}
function nav(){
 const current=route.startsWith('customer')?'customers':route.startsWith('product')?'products':['quote','order','orders'].includes(route)?'orders':['settings','notifications','inventory','inventory-edit','agenda','more'].includes(route)?'more':route;
 const icons={home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z"/>',products:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',customers:'<circle cx="12" cy="8" r="4"/><path d="M4 21v-2a6 6 0 0 1 6-6h4a6 6 0 0 1 6 6v2"/>',orders:'<rect x="5" y="3" width="14" height="18" rx="2"/><path d="M9 8h6M9 12h6M9 16h4"/>',more:'<path d="M4 6h16M4 12h16M4 18h16"/>'};
 $('#navigation').innerHTML=[['home','Início'],['products','Produtos'],['customers','Clientes'],['orders','Pedidos'],['more','Mais']].map(([name,label])=>`<button data-action="nav" data-id="${name}" class="${name===current?'active':''}"><span aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">${icons[name]}</svg></span>${label}</button>`).join('');
}
function render(){
 renderBrand();$('#demo-banner').hidden=mode!=='demo';nav();
 const pages={home:homePage,products:productsPage,'product-edit':productForm,customers:customersPage,'customer-edit':customerForm,'customer-detail':customerDetail,orders:ordersPage,order:orderPage,quote:quotePage,more:morePage,settings:settingsPage,notifications:notificationsPage,inventory:inventoryPage,'inventory-edit':inventoryForm,agenda:agendaPage};
 app.innerHTML=(pages[route]||homePage)();
}
function renderBrand(){
 $('#shop-name').textContent=state.settings.name;document.title=state.settings.name+' · Gestão';
 const box=$('#brand-logo'),src=state.images[state.settings.logo];box.replaceChildren();
 const valid=typeof src==='string'&&/^data:image\/(?:jpeg|png|webp);base64,/.test(src);box.classList.toggle('has-logo',valid);
 if(valid){const logo=document.createElement('img');logo.alt='Logo da confeitaria';logo.src=src;box.append(logo);}else box.textContent='🧁';
}
function notificationsPage(){
 const s={...L.reminderDefaults,...state.settings},status=window.Android?JSON.parse(Android.reminderStatus()):{};
 if(mode==='demo')return button('Voltar','nav','more','back')+heading('LEMBRETES','Alertas e e-mail')+'<div class="info">A demonstração não envia avisos. Volte aos seus dados para configurar notificações.</div>';
 return button('Voltar','nav','more','back')+heading('LEMBRETES','Alertas e e-mail','Prepare a produção com antecedência e receba avisos das encomendas com data reservada.')+
 `<div class="card"><form data-form="notifications">${check('Ativar lembretes de encomendas','reminders_enabled',s.reminders_enabled)}${check('Mostrar notificações neste celular','local_notifications',s.local_notifications)}<label>Quando lembrar?</label><div class="reminder-days">${[7,3,2,1,0].map(d=>check(d===0?'No dia':d+' dia(s) antes','alert_days',s.alert_days.includes(d),d)).join('')}</div>${field('Horário dos avisos','alert_time',s.alert_time,'time','required')}<p class="hint">Horário deste celular. Pedidos entregues não geram novos avisos. O Android verifica em segundo plano, mesmo após fechar a tela; a economia de bateria pode atrasar os avisos. Depois de forçar a parada do app, abra-o novamente.</p>${field('E-mail para receber notificações','notification_email',s.notification_email,'email')}${check('Enviar também por e-mail','email_enabled',s.email_enabled)}<details><summary>Configurar o envio de e-mail</summary><p class="hint">Use uma conta de envio e sua senha de aplicativo. No Gmail, gere uma senha de aplicativo na Conta Google com verificação em duas etapas. O destinatário pode ser diferente do remetente.</p>${field('Servidor SMTP','smtp_host',s.smtp_host)}<div class="grid">${field('Porta SMTP','smtp_port',s.smtp_port,'number','min="1" max="65535" required')}${select('Segurança do e-mail','smtp_security',['SSL/TLS','STARTTLS'],s.smtp_security)}</div>${field('Usuário SMTP','smtp_username',s.smtp_username)}${field('E-mail do remetente','smtp_sender',s.smtp_sender,'email')}${field('Senha de aplicativo do e-mail','smtp_password','','password','autocomplete="new-password"')}<p class="hint">${status.has_password?'Senha já configurada. Deixe em branco para mantê-la.':'A senha ficará cifrada neste aparelho.'} Ela não entra no backup dos cadastros.</p></details>${formError()}<button class="primary full" type="submit">Salvar alertas</button></form></div><div class="card"><h2>Permissão de notificações</h2><p>${status.permission?'Notificações permitidas neste celular.':'Permita os avisos para receber notificações fora do aplicativo.'}</p><div class="toolbar">${button('Permitir notificações','request-notifications')}${button('Abrir permissões','notification-settings')}</div>${button('Enviar e-mail de teste','test-email','','full')}${status.last_check?'<p class="hint">Última verificação: '+E(dateLabel(status.last_check.slice(0,10),status.last_check.slice(11,16)))+'</p>':''}${status.error?'<div class="warning">'+E(status.error)+'</div>':''}</div>`;
}
function reminderPanel(){
 if(!state.settings.reminders_enabled)return '';
 const max=Math.max(...(state.settings.alert_days||[3,2])),now=new Date();
 const rows=state.quotes.filter(q=>L.status(q).includes('Data Reservada')&&new Date(q.event_date+'T'+q.event_time)>now&&q.event_date<=L.plusDays(L.today(),max));
 return rows.length?`<div class="warning"><strong>🔔 ${rows.length} encomenda(s) se aproximando</strong>${rows.slice(0,4).map(q=>'<p>#'+String(q.number).padStart(4,'0')+' · '+E(q.customer.name)+' · '+dateLabel(q.event_date,q.event_time)+'</p>').join('')}${button('Ver agenda','nav','agenda','small')}</div>`:'';
}
function homePage(){const orders=state.quotes,approved=orders.filter(q=>L.status(q).includes('Data Reservada')),upcoming=approved.filter(q=>q.event_date>=L.today()).sort((a,b)=>(a.event_date+a.event_time).localeCompare(b.event_date+b.event_time));return heading('PAINEL DA CONFEITARIA','Sua confeitaria em dia','Pedidos, produção e recebimentos no seu celular.')+reminderPanel()+`<div class="grid">${metric('Saídas de hoje',approved.filter(q=>q.event_date===L.today()).length)}${metric('Datas reservadas',approved.length)}${metric('A receber · reservados',L.money(approved.reduce((s,q)=>s+q.totals.total_cents-L.paid(q),0)))}${metric('Recebido · acumulado',L.money(orders.reduce((s,q)=>s+L.paid(q),0)))}</div><div class="toolbar">${button('Novo orçamento','new-quote','','primary')}${button('Agenda da cozinha','nav','agenda')}</div><h2>Próximas encomendas</h2>${upcoming.length?upcoming.slice(0,5).map(orderRow).join(''):empty('Sua próxima criação começa aqui','Cadastre um cliente e prepare o primeiro orçamento.')}<div class="card"><h3>${mode==='demo'?'Voltar ao trabalho':'Conheça o visual preenchido'}</h3><p class="hint">${mode==='demo'?'A demonstração usa um banco separado.':'Veja produtos ilustrados, clientes e pedidos fictícios sem alterar seus dados.'}</p>${button(mode==='demo'?'Voltar aos meus dados':'Abrir demonstração','demo')}</div>`;}
function productsPage(){const rows=state.products.filter(p=>p.active&&(productCategory==='Todas'||p.category===productCategory)&&[p.name,p.description].join(' ').toLowerCase().includes(filter.toLowerCase()));return heading('VITRINE','Produtos e sabores','Fotos padronizadas, descrições e preços da confeitaria.')+`<div class="toolbar">${button('Novo produto','nav','product-edit','primary')}</div><input aria-label="Buscar produto" placeholder="Nome ou descrição…" data-search="products" value="${E(filter)}">${select('Categoria do catálogo','catalog_category',['Todas',...L.categories],productCategory)}<p class="hint">Ilustrações iniciais são exemplos. Substitua pelas fotos dos seus produtos.</p><div class="products">${rows.map(p=>{const current=L.price(p);return `<article class="product card">${image(p.photos[0])}<small class="category">${E(p.category)}</small><h3>${E(p.name)}</h3>${current.promotional?'<span class="badge coral">PROMOÇÃO</span>':''}<span class="price">${current.value?L.money(current.value)+' / '+p.unit:'Preço a cadastrar'}</span><p class="description">${E(p.description)}</p>${button('Ver detalhes','product-view',p.id,'small')} ${button('Editar','nav','product-edit:'+p.id,'small')}</article>`;}).join('')}</div>${!rows.length?empty('Nenhum produto encontrado','Ajuste a busca ou cadastre uma nova criação.'):''}`;}
function productForm(){const p=state.products.find(p=>p.id===entity)||{category:L.categories[0],active:true,photos:[]};if(!formPhotos.product)formPhotos.product=[...(p.photos||[])];return button('Voltar para produtos','nav','products','back')+heading('CATÁLOGO',p.id?'Editar produto':'Novo produto')+`<div class="card">${formShell('product',field('Nome do produto *','name',p.name,'text','required maxlength="150"')+select('Categoria *','category',L.categories,p.category)+area('Descrição completa','description',p.description)+area('Composição / itens inclusos · um por linha','composition',(p.composition||[]).join('\n'))+field('Preço normal por kg / cento / unidade (R$)','price',(p.price_cents||0)/100,'number','min="0" step="0.01" required')+check('Visível no catálogo','active',p.active)+`<details><summary>Promoção do dia / mês</summary>${check('Ativar preço promocional no período','promo_enabled',p.promo_enabled)}${field('Preço promocional (R$)','promo',(p.promo_cents||0)/100,'number','min="0" step="0.01"')}<div class="grid">${field('Início','promo_start',p.promo_start,'date')}${field('Fim','promo_end',p.promo_end,'date')}</div></details>`+photoInput('Fotos do produto · até três','product',true))}</div>`;}
function customersPage(){const rows=state.customers.filter(c=>(customerFilter==='Todos'||!!c.active===(customerFilter==='Ativos'))&&[c.name,c.phone,c.email,c.cpf].join(' ').toLowerCase().includes(filter.toLowerCase())).sort((a,b)=>a.name.localeCompare(b.name,'pt-BR'));const size=12,pages=Math.max(1,Math.ceil(rows.length/size));page=Math.min(page,pages);return heading('ATENDIMENTO','Clientes','Contatos e endereços organizados em uma lista compacta.')+`<div class="toolbar">${button('Novo cliente','nav','customer-edit','primary')}</div><div class="grid three">${metric('Ativos',state.customers.filter(c=>c.active).length)}${metric('Com pedidos',new Set(state.quotes.map(q=>q.customer_id)).size)}${metric('Com endereço',state.customers.filter(c=>c.street&&c.number&&c.city).length)}</div><div class="toolbar"><input aria-label="Buscar cliente" data-search="customers" placeholder="Nome, telefone, e-mail ou CPF" value="${E(filter)}"></div>${select('Mostrar clientes','customer_filter',['Ativos','Arquivados','Todos'],customerFilter)}<p class="hint">${rows.length} cliente(s) · Deslize a tabela para ver as ações.</p><div class="sheet"><table><thead><tr><th>CLIENTE</th><th>TELEFONE</th><th>E-MAIL</th><th>CIDADE / UF</th><th>AÇÕES</th></tr></thead><tbody>${rows.slice((page-1)*size,page*size).map(c=>`<tr><td><div class="person">${avatar(c)}<div><b>${E(c.name)}</b><small>${state.quotes.filter(q=>q.customer_id===c.id).length} pedido(s)</small></div></div></td><td>${E(c.phone)}</td><td>${E(c.email||'—')}</td><td>${E([c.city,c.state].filter(Boolean).join(' / ')||'—')}</td><td>${button('Abrir','nav','customer-detail:'+c.id,'small')} ${button('Editar','nav','customer-edit:'+c.id,'small')} ${button(c.active?(state.quotes.some(q=>q.customer_id===c.id)?'Arquivar':'Excluir'):'Restaurar',c.active?'delete-customer':'restore-customer',c.id,'small')}</td></tr>`).join('')}</tbody></table></div>${!rows.length?empty('Seus clientes, bem cuidados','Cadastre um cliente ou ajuste a pesquisa.'):''}<div class="toolbar">${page>1?button('Anterior','page',String(page-1)):''}<span class="hint">Página ${page} de ${pages} · 12 por página</span>${page<pages?button('Próxima','page',String(page+1)):''}</div>`;}
function customerFields(c={}){if(!formPhotos.customer)formPhotos.customer=c.photo||'';return field('Nome completo *','name',c.name,'text','required minlength="2" maxlength="150"')+`<div class="grid">${field('Telefone / WhatsApp *','phone',c.phone,'tel','required maxlength="22"')}${field('CPF','cpf',c.cpf,'text','inputmode="numeric" maxlength="14"')}</div>`+field('E-mail','email',c.email,'email')+`<h3 style="margin-top:22px">Endereço de entrega</h3><div class="grid">${field('CEP','postal_code',c.postal_code,'text','inputmode="numeric" maxlength="9" data-cep="1"')}<div style="align-self:end">${button('Buscar endereço','cep','','full')}</div></div><p class="hint" id="cep-message">O CEP preenche rua, bairro, cidade e UF quando há internet.</p>${field('Rua / avenida','street',c.street)}<div class="grid">${field('Número','number',c.number)}${field('Complemento','complement',c.complement)}</div>${field('Bairro','neighborhood',c.neighborhood)}<div class="grid">${field('Cidade','city',c.city)}${select('Estado (UF)','state',['','AC','AL','AP','AM','BA','CE','DF','ES','GO','MA','MT','MS','MG','PA','PB','PR','PE','PI','RJ','RN','RS','RO','RR','SC','SP','SE','TO'],c.state)}</div>${field('Ponto de referência','address_reference',c.address_reference)}${area('Observações do cliente','notes',c.notes)}${photoInput('Foto do cliente','customer')}`;}
function customerForm(){const c=state.customers.find(c=>c.id===entity)||{};return button('Voltar para clientes','nav','customers','back')+heading('CADASTRO',c.id?'Editar cliente':'Novo cliente','Nome e telefone são obrigatórios. Complete os demais dados quando precisar.')+`<div class="card">${formShell('customer',customerFields(c))}</div>`;}
function customerDetail(){const c=state.customers.find(c=>c.id===entity);if(!c)return empty('Cliente não encontrado','Volte à lista e confira o cadastro.');const history=state.quotes.filter(q=>q.customer_id===c.id);return button('Voltar para clientes','nav','customers','back')+heading('CADASTRO',c.name)+`<div class="card"><div class="person">${avatar(c)}<div><b>${E(c.name)}</b><small>${c.active?'Cliente ativo':'Arquivado'}</small></div></div><div class="separator"></div><div class="details-grid"><div><small>WhatsApp</small><p>${E(c.phone)}</p></div><div><small>E-mail</small><p>${E(c.email||'—')}</p></div><div><small>CPF</small><p>${E(c.cpf||'—')}</p></div><div><small>Endereço</small><p>${E(L.address(c)||'—')}</p></div></div><p class="hint">${E(c.address_reference||'')}</p><p>${E(c.notes||'')}</p><div class="toolbar">${button('Editar cliente','nav','customer-edit:'+c.id)}${c.active?button('Novo orçamento','new-quote',c.id,'primary'):''}</div></div><h2>Histórico de pedidos</h2>${history.length?history.map(orderRow).join(''):empty('Nenhum pedido por aqui','Os orçamentos ficam vinculados ao cadastro.')}`;}
function orderRow(q){return `<article class="order-row"><div><strong>#${String(q.number).padStart(4,'0')} · ${E(q.customer.name)}</strong><p>${E(dateLabel(q.event_date,q.event_time))}</p>${statusBadge(q)}</div><div class="right"><b>${L.money(q.totals.total_cents)}</b><p>Saldo ${L.money(q.totals.total_cents-L.paid(q))}</p>${button('Ver pedido','nav','order:'+q.id,'small')}</div></article>`;}
function ordersPage(){const rows=state.quotes.filter(q=>(orderFilter==='Todos'||!!q.delivered===(orderFilter==='Fechados'))&&[q.customer.name,String(q.number)].join(' ').toLowerCase().includes(filter.toLowerCase())).sort((a,b)=>b.number-a.number);return heading('ATENDIMENTO','Pedidos e pagamentos','Abra os detalhes somente quando precisar.')+`<div class="toolbar">${button('Novo orçamento','new-quote','','primary')}</div><div class="chip-row">${['Todos','Abertos','Fechados'].map(name=>button(name,'order-filter',name,name===orderFilter?'active':'')).join('')}</div><input aria-label="Buscar pedido" data-search="orders" placeholder="Nome do cliente ou número" value="${E(filter)}"><p class="hint">Abertos: ainda não entregues. Fechados: entrega / retirada concluída.</p>${rows.map(orderRow).join('')||empty('Nenhum orçamento neste filtro','Crie uma encomenda ou ajuste a pesquisa.')}`;}
function linesHtml(lines,editable=false){return lines.map((line,i)=>`<div class="card"><div class="summary-line"><b>${E(line.name)}${line.gift?' [BRINDE]':''}</b><b>${L.money(line.total_cents)}</b></div><p class="hint">${E(String(line.quantity).replace('.',','))} ${E(line.unit)} · ${E([...line.fillings,...line.flavors].join(' / '))}</p>${line.composition.length?`<p class="hint">Inclui: ${E(line.composition.join('; '))}</p>`:''}${line.extras.map(e=>`<p class="hint">＋ ${e.quantity} × ${E(e.name)} · ${e.gift||line.gift?'[BRINDE]':L.money(e.amount_cents)}${e.flavors?.length?'<br>'+E(e.brigadeiro_type+' · '+e.flavors.join(' / ')):''}${e.personalization?'<br>'+E(e.personalization):''}</p>${e.reference_photo?image(e.reference_photo,true):''}`).join('')}${line.details?`<p>${E(line.details)}</p>`:''}${line.negotiation?.notes?`<div class="warning">Exceção autorizada: ${E(line.negotiation.notes)}</div>`:''}${line.reference_photo?image(line.reference_photo,true):''}${editable?`<div class="toolbar">${button('Editar item','edit-line',String(i),'small')}${button('Remover','remove-line',String(i),'small danger')}</div>`:''}</div>`).join('');}
function orderPage(){const q=state.quotes.find(q=>q.id===entity);if(!q)return empty('Pedido não encontrado','Confira a lista de pedidos.');const received=L.paid(q),balance=q.totals.total_cents-received,minimum=Math.max(0,q.totals.deposit_cents-received);return button('Voltar para pedidos','nav','orders','back')+heading('PEDIDO #'+String(q.number).padStart(4,'0'),q.customer.name,dateLabel(q.event_date,q.event_time))+statusBadge(q)+`<p class="hint">Validade: ${dateLabel(q.valid_until)} · ${E(q.fulfillment)}</p><div class="grid">${metric('Total acordado',L.money(q.totals.total_cents))}${metric('Entrada mínima · 50%',L.money(q.totals.deposit_cents))}${metric('Recebido',L.money(received))}${metric('Saldo devedor',L.money(balance))}</div><p class="hint">${E(q.delivery_address||'Retirada na loja')}</p><h2 style="margin-top:24px">Itens da encomenda</h2>${linesHtml(q.lines)}<div class="card"><h3>Observações</h3><p>${E(q.notes||'Nenhuma observação geral.')}</p><h3 style="margin-top:18px">Decoração, alergias e transporte</h3><p>${E(q.production_notes||'Nenhuma orientação registrada.')}</p></div>${!received&&!q.delivered?`<div class="toolbar">${button('Editar orçamento','edit-order',q.id)}</div>`:''}${L.status(q)==='Vencido'?`<div class="warning">Renove o prazo antes de receber pagamentos.</div>${button('Renovar por sete dias','renew-order',q.id)}`:''}<div class="card"><h2>Recebimentos</h2>${q.payments.map(p=>`<p><b>${L.money(p.amount_cents)}</b> · ${E(p.method)}<br><small class="hint">${E(p.note)} · ${new Date(p.received_at).toLocaleDateString('pt-BR')}</small></p>`).join('')||'<p class="hint">Nenhum pagamento registrado.</p>'}${balance>0&&L.status(q)!=='Vencido'?`<form data-form="payment">${check('Entrada de 50% recebida (sinal)','deposit',minimum>0)}${field('Valor recebido agora (R$)','amount',(minimum||balance)/100,'number','min="0.01" step="0.01" required')}${select('Forma deste recebimento','method',['PIX','Dinheiro','Cartão'],q.payment_method)}${field('Descrição / comprovante','note')}${check('Confirmo que este valor já foi recebido','confirmed')}${formError()}<button class="primary full" type="submit">Registrar recebimento</button></form>`:''}${balance===0?'<div class="info">Pagamento integral recebido.</div>':''}${balance===0&&!q.delivered?button('Concluir entrega / retirada','deliver-order',q.id,'primary full'):''}</div><div class="card"><h2>PDFs e compartilhamento</h2><p class="hint">O orçamento leva os valores; a ficha da cozinha leva os detalhes e as fotos de inspiração.</p><div class="toolbar">${button('Salvar orçamento PDF','pdf',q.id+':client')}${button('Compartilhar orçamento','pdf',q.id+':share')}</div><div class="toolbar">${button('Salvar ficha da cozinha','pdf',q.id+':kitchen')}${button('Compartilhar ficha','pdf',q.id+':kitchen-share')}</div>${q.shop.logo?image(q.shop.logo,true):''}${photoInput('Adicionar / trocar logo deste pedido','orderLogo')}${button('Aplicar logo ao pedido','order-logo',q.id)}</div>`;}
function newDraft(customer=''){return {customer_id:customer,event_date:L.plusDays(L.today(),7),event_time:'14:00',fulfillment:'Retirada',delivery_address:'',lines:[],step:0,payment_method:'PIX',pix_enabled:false,pix_percent:0,discount_cents:0,delivery_cents:0,notes:'',production_notes:'',logo:''};}
function quotePage(){if(!draft)draft=newDraft();const stages=['Cliente','Produtos','Pagamento','Revisão'];let content='';if(draft.step===0){const c=state.customers.find(c=>c.id===draft.customer_id);content=`<form data-form="quote-client"><div class="card"><h2>Para quem é esta encomenda?</h2>${select('Cliente *','customer_id',[['','Escolha um cliente'],...state.customers.filter(c=>c.active).map(c=>[c.id,c.name+' · '+c.phone])],draft.customer_id,'required')}${button('Novo cliente','inline-customer','','small')}${c?`<p class="hint">${E(L.address(c)||'Endereço ainda não informado.')}</p>`:''}<div class="grid">${field('Data da encomenda','event_date',draft.event_date,'date',`required min="${L.today()}"`)}${field('Horário de saída','event_time',draft.event_time,'time','required')}</div>${select('Recebimento','fulfillment',['Retirada','Entrega'],draft.fulfillment)}${area('Endereço de entrega · se aplicável','delivery_address',draft.delivery_address||L.address(c||{}))}</div>${formError()}<button class="primary full" type="submit">Continuar para produtos</button></form>`;}
 else if(draft.step===1)content=builderForm()+`<h2>Itens do pedido · ${draft.lines.length}</h2>${linesHtml(draft.lines,true)}<div class="toolbar">${button('Voltar','quote-back')}${button('Continuar para pagamento','quote-next','','primary')}</div>`;
 else if(draft.step===2)content=`<form data-form="quote-payment"><div class="card"><h2>Como será o pagamento?</h2>${select('Forma de pagamento','payment_method',['PIX','Dinheiro','Cartão'],draft.payment_method)}${check('Conceder desconto PIX / Dinheiro','pix_enabled',draft.pix_enabled)}${field('Desconto PIX / Dinheiro (%)','pix_percent',draft.pix_percent,'number','min="0" max="100" step="0.5"')}<p class="hint">O desconto só é aplicado quando você marca a opção. Produtos em promoção podem acumular desconto se você decidir.</p>${draft.lines.some(l=>l.promotional)&&draft.pix_enabled?'<div class="warning">Há itens em promoção. O desconto será acumulado porque você ativou a opção.</div>':''}<div class="grid">${field('Desconto geral (R$)','discount',draft.discount_cents/100,'number','min="0" step="0.01"')}${field('Entrega / frete (R$)','delivery',draft.delivery_cents/100,'number','min="0" step="0.01"')}</div></div><div class="card">${area('Observações para o cliente','notes',draft.notes)}${area('Orientações para a cozinha','production_notes',draft.production_notes)}</div>${formError()}<div class="toolbar">${button('Voltar','quote-back')}<button class="primary" type="submit">Revisar orçamento</button></div></form>`;
 else {const c=state.customers.find(c=>c.id===draft.customer_id);content=`<div class="card"><h2>Confira antes de salvar</h2><b>${E(c?.name)}</b><p>${E(dateLabel(draft.event_date,draft.event_time))} · ${E(draft.fulfillment)}</p><p class="hint">${E(draft.fulfillment==='Entrega'?draft.delivery_address:'Retirada na loja')}</p>${button('Alterar cliente / entrega','quote-step','0','small')}</div>${linesHtml(draft.lines)}<div class="card"><h3>Observações para o cliente</h3><p>${E(draft.notes||'—')}</p><h3>Orientações para a cozinha</h3><p>${E(draft.production_notes||'—')}</p>${photoInput('Logo da loja neste orçamento','quoteLogo')}<p class="hint">A logo padrão é cadastrada em Configurações. Validade de sete dias; data reservada após o recebimento de pelo menos 50%.</p></div><div class="toolbar">${button('Voltar','quote-back')}${button('Salvar orçamento','save-quote','','primary')}</div>`;}
 return heading('ORÇAMENTO',draft.id?'Editar orçamento':'Nova encomenda','Monte o pedido em quatro etapas.')+`<div class="steps">${stages.map((name,i)=>`<div class="step ${i===draft.step?'active':''}">${i+1} · ${name}</div>`).join('')}</div>${content}${draft.lines.length?summaryHtml():''}`;}
function summaryHtml(){try{const t=L.totals(draft.lines,draft);return `<div class="card"><h3>Resumo do orçamento</h3>${[['Subtotal',t.subtotal_cents],['Desconto geral',-t.discount_cents],['Desconto PIX',-t.pix_discount_cents],['Entrega',t.delivery_cents]].map(([label,value])=>`<div class="summary-line"><span>${label}</span><b>${L.money(value)}</b></div>`).join('')}<div class="summary"><small>Total do pedido</small><strong>${L.money(t.total_cents)}</strong></div><p class="hint">Sinal para reservar a data: <b>${L.money(t.deposit_cents)}</b></p></div>`;}catch(exc){return `<div class="error">${E(exc.message)}</div>`;}}
function getBuilderProduct(){return state.products.find(p=>p.id===builder?.product_id&&p.active)||state.products.find(p=>p.active);}
function builderForm(){const products=state.products.filter(p=>p.active);if(!products.length)return empty('Cadastre um produto','Ative um produto no catálogo antes de montar o orçamento.');if(!builder){const first=products.find(p=>p.category===L.categories[0])||products[0];builder={product_id:first.id,quantity:L.fillings[first.category]?2:1,fillings:[],extras:[],flavors:[],details:'',gift:false,reference_photo:''};}const p=getBuilderProduct(),isCake=!!L.fillings[p.category],limit=builder.quantity<2?1:2;builder.product_id=p.id;const kind=builder.brigadeiro_type||(/Personalizados/.test(p.name)?'Personalizado':/Especiais/.test(p.name)?'Especial':'Tradicional');let fields='';
 if(isCake){fields=`<h3 id="filling-heading" style="margin-top:20px">Escolha até ${limit} recheio(s)</h3><p class="hint">Padrão: mínimo de 2 kg. Abaixo de 2 kg: um recheio. A partir de 2 kg: até dois.</p><div class="grid">${L.fillings[p.category].map(f=>check(f,'fillings',builder.fillings.includes(f),f)).join('')}</div><div id="cake-exception">${exceptionFields()}</div><details ${builder.extras.length?'open':''}><summary>Decoração e adicionais</summary>${L.extras.map((name,i)=>{const old=builder.extras.find(e=>e.name===name);return `<div>${check(name,'extras',!!old,name)}${old?`<fieldset><div class="grid">${field('Quantidade · '+name,'extra_'+i+'_quantity',old.quantity||1,'number','min="1" step="1"')}${field('Valor unitário (R$) · '+name,'extra_'+i+'_price',(old.unit_cents||0)/100,'number','min="0" step="0.01"')}</div>${check('É cortesia · '+name,'extra_'+i+'_gift',old.gift)}${name==='Brigadeiros no Topo'?select('Tipo dos brigadeiros adicionais','extra_'+i+'_type',Object.keys(L.brigadeiros),old.brigadeiro_type||'Tradicional')+`<div class="grid">${L.brigadeiros[old.brigadeiro_type||'Tradicional'].map(flavor=>check(flavor+' · adicional','extra_'+i+'_flavors',(old.flavors||[]).includes(flavor),flavor)).join('')}</div>`+((old.brigadeiro_type==='Personalizado')?field('Personalização dos brigadeiros adicionais','extra_'+i+'_personalization',old.personalization):''):''}${name.includes('Topo de Bolo')?photoInput('Imagem de inspiração do topo','extra_'+i):''}<p class="hint" id="extra_total_${i}">${old.quantity||1} × ${L.money(old.unit_cents||0)} = ${old.gift?'[BRINDE]':L.money((old.quantity||1)*(old.unit_cents||0))}</p></fieldset>`:''}</div>`;}).join('')}</details>`;}
 if(p.category==='Cento de Brigadeiros')fields=select('Tipo de brigadeiro','brigadeiro_type',Object.keys(L.brigadeiros),kind)+check('Dividir cento em 50/50','split',builder.split)+select('Sabor 1','flavor_1',L.brigadeiros[kind],builder.flavors[0]||L.brigadeiros[kind][0])+(builder.split?select('Sabor 2','flavor_2',L.brigadeiros[kind],builder.flavors[1]||L.brigadeiros[kind][1])+'<p class="hint">50 unidades de cada sabor por cento.</p>':'')+(kind==='Personalizado'?'<div class="info">Descreva o tema, as cores e a personalização nos detalhes deste item.</div>':'');
 formPhotos.itemReference=builder.reference_photo||'';for(const extra of builder.extras){const i=L.extras.indexOf(extra.name);if(extra.reference_photo)formPhotos['extra_'+i]=extra.reference_photo;}
 return `<form id="builder-form" data-form="line"><div class="card"><h2>O que vamos preparar?</h2>${select('Categoria','builder_category',L.categories.filter(c=>products.some(p=>p.category===c)),p.category)}${select('Produto','product_id',products.filter(x=>x.category===p.category).map(x=>[x.id,x.name]),p.id)}${image(p.photos[0])}<b>${L.money(L.price(p).value)} / ${E(p.unit)}</b><p>${E(p.description)}</p>${p.composition.length?`<h3>Este kit inclui</h3><ul class="item-list">${p.composition.map(item=>'<li>• '+E(item)+'</li>').join('')}</ul>`:''}${field(isCake?'Peso do bolo (kg)':p.unit==='cento'?'Quantidade de centos':'Quantidade de unidades','quantity',builder.quantity,'number',`min="1" max="100000" step="${isCake?'0.5':'1'}" required`)}${fields}<details ${builder.details||builder.gift?'open':''}><summary>Personalização e cortesia</summary>${area('Detalhes deste item','details',builder.details)}${check('Este item é brinde / cortesia','gift',builder.gift)}</details>${photoInput('Imagem de inspiração deste item','itemReference')}${formError()}<button type="submit" class="primary full">${editingLine>=0?'Salvar alterações do item':'Adicionar ao pedido'}</button>${editingLine>=0?button('Cancelar edição','cancel-line','','full'):''}</div></form>`;
}
function morePage(){return heading('SUA CONFEITARIA','Tudo no lugar','Produção, estoque e proteção dos dados.')+`<div class="card"><div class="toolbar">${button('Agenda da cozinha','nav','agenda','full')}</div><div class="toolbar">${button('Estoque e insumos','nav','inventory','full')}</div><div class="toolbar">${button('Configurações e backup','nav','settings','full')}</div><div class="toolbar">${button('Alertas e e-mail','nav','notifications','full')}</div><div class="toolbar">${button(mode==='demo'?'Voltar aos meus dados':'Ver demonstração','demo','','full')}</div></div><p class="hint">Android · versão 1.1.0. Os dados ficam neste celular. O aplicativo funciona sem internet; a consulta de CEP precisa de conexão. O banco do Windows é independente.</p>`;}
function settingsPage(){const s=state.settings;if(!Object.hasOwn(formPhotos,'logo'))formPhotos.logo=s.logo||'';return button('Voltar','nav','more','back')+heading('IDENTIDADE DA LOJA','Configurações e backup','Escolha o nome e a logo que aparecem no cabeçalho do sistema e nos próximos orçamentos.')+`<div class="card">${formShell('settings',field('Nome da confeitaria *','name',s.name,'text','required maxlength="150"')+field('WhatsApp da loja','phone',s.phone,'tel')+field('CNPJ / CPF da loja','document',s.document)+area('Endereço da loja','address',s.address)+field('Alterações aceitas até quantos dias antes?','change_days',s.change_days,'number','min="0" max="365" step="1" required')+photoInput('Logo da confeitaria · cabeçalho e PDFs','logo'))}</div><div class="card"><h2>Cópia de segurança</h2><p>O backup reúne cadastros, pedidos, recebimentos e fotos. Salve uma cópia fora do celular regularmente.</p><p class="warning">Desinstalar o aplicativo ou limpar seus dados apaga o banco deste celular. O backup Android é próprio deste aplicativo e não importa automaticamente o ZIP da versão Windows.</p><div class="toolbar">${button('Salvar backup completo','backup','','primary')}${button('Restaurar backup','import')}</div>${button('Recuperar cópia anterior à restauração','restore-point','','small')}</div>`;}
function inventoryPage(){const rows=state.inventory.filter(i=>[i.name,i.brand].join(' ').toLowerCase().includes(filter.toLowerCase()));return button('Voltar','nav','more','back')+heading('PRODUÇÃO','Estoque e insumos','Materiais, marcas e custo por unidade de conteúdo.')+`<div class="toolbar">${button('Novo insumo','nav','inventory-edit','primary')}</div><input data-search="inventory" aria-label="Buscar insumo" placeholder="Nome ou marca" value="${E(filter)}"><div class="products" style="margin-top:15px">${rows.map(i=>`<article class="product card">${image(i.photo)}<h3>${E(i.name)}</h3><p>${E(i.brand||'Marca não informada')}</p><p>Conteúdo: ${i.content} ${E(i.content_unit)}<br>Estoque: ${i.stock} ${E(i.package_unit)}<br>Pago por embalagem: ${L.money(i.paid_cents)}</p><b>Custo: R$ ${(i.paid_cents/100/i.content).toFixed(4).replace('.',',')} / ${E(i.content_unit)}</b><div class="toolbar">${button('Editar','nav','inventory-edit:'+i.id,'small')}</div></article>`).join('')}</div>${!rows.length?empty('Seu estoque começa aqui','Cadastre ingredientes, embalagens e materiais.'):''}`;}
function inventoryForm(){const i=state.inventory.find(i=>i.id===entity)||{content:1000,content_unit:'g',stock:0,package_unit:'Un',paid_cents:0};if(!formPhotos.inventory)formPhotos.inventory=i.photo||'';return button('Voltar para estoque','nav','inventory','back')+heading('INSUMOS',i.id?'Editar insumo':'Novo insumo')+`<div class="card">${formShell('inventory',field('Nome *','name',i.name,'text','required')+field('Marca','brand',i.brand)+`<div class="grid">${field('Conteúdo por embalagem','content',i.content,'number','min="0.001" step="0.001" required')}${select('Unidade do conteúdo','content_unit',['g','ml','unidade'],i.content_unit)}</div><div class="grid">${field('Quantidade em estoque','stock',i.stock,'number','min="0" step="0.001" required')}${select('Unidade do estoque','package_unit',L.units,i.package_unit)}</div>`+field('Valor pago por embalagem (R$)','paid',i.paid_cents/100,'number','min="0" step="0.01" required')+'<p class="hint">Exemplo: 1.000 ml por R$ 5,00 = R$ 0,0050/ml. O estoque informa a quantidade de embalagens.</p>'+photoInput('Foto do insumo / embalagem','inventory'))}</div>`;}
function agendaPage(){const [year,month]=activeMonth.split('-').map(Number),start=new Date(year,month-1,1),count=new Date(year,month,0).getDate(),offset=(start.getDay()+6)%7;const approved=state.quotes.filter(q=>L.status(q).includes('Data Reservada'));return button('Voltar','nav','more','back')+heading('PRODUÇÃO','Agenda da cozinha','Somente encomendas com data reservada e ainda não entregues.')+field('Mês da agenda','agenda_month',activeMonth,'month')+`<div class="calendar">${['Seg','Ter','Qua','Qui','Sex','Sáb','Dom'].map(name=>'<div class="day-name">'+name+'</div>').join('')}${'<span></span>'.repeat(offset)}${Array.from({length:count},(_,i)=>{const day=activeMonth+'-'+String(i+1).padStart(2,'0'),n=approved.filter(q=>q.event_date===day).length;return button(String(i+1)+(n?' · '+n:''),'agenda-day',day,(n?'has-orders ':'')+(day===activeDay?'selected':''));}).join('')}</div><h2>${dateLabel(activeDay)}</h2>${approved.filter(q=>q.event_date===activeDay).sort((a,b)=>a.event_time.localeCompare(b.event_time)).map(orderRow).join('')||empty('Nenhuma saída confirmada','Receba o sinal mínimo para reservar uma encomenda.')}`;}

function exceptionFields(){return builder.quantity<2||builder.fillings.length>(builder.quantity<2?1:2)?`<div class="warning">Peso ou recheios fora do padrão. Só continue com uma condição negociada e confirmada pela confeiteira.</div>${check('Confirmar exceção combinada com a confeiteira','exception',builder.exception)}${field('Motivo / condição da exceção','negotiation',builder.negotiation||'')}`:'';}
function collectBuilder(){const form=$('#builder-form');if(!form||!builder)return;const data=new FormData(form),p=getBuilderProduct();builder.quantity=Number(data.get('quantity'));builder.fillings=data.getAll('fillings');builder.details=data.get('details')||'';builder.gift=data.has('gift');builder.exception=data.has('exception');builder.negotiation=data.get('negotiation')||'';builder.reference_photo=formPhotos.itemReference||'';builder.brigadeiro_type=data.get('brigadeiro_type')||'';builder.split=data.has('split');builder.flavors=[data.get('flavor_1'),builder.split?data.get('flavor_2'):null].filter(Boolean);builder.extras=data.getAll('extras').map(name=>{const i=L.extras.indexOf(name),previous=builder.extras.find(e=>e.name===name)||{};return {name,quantity:Number(data.get('extra_'+i+'_quantity')||previous.quantity||1),unit_cents:data.has('extra_'+i+'_price')?L.amount(data.get('extra_'+i+'_price')):previous.unit_cents||0,gift:data.has('extra_'+i+'_gift'),brigadeiro_type:data.get('extra_'+i+'_type')||previous.brigadeiro_type||'Tradicional',flavors:data.getAll('extra_'+i+'_flavors'),personalization:data.get('extra_'+i+'_personalization')||'',reference_photo:formPhotos['extra_'+i]||''};});return p;}
function collectQuote(){const form=app.querySelector('form');if(!draft||!form||draft.step===1)return;const data=new FormData(form);if(draft.step===0){const old=draft.customer_id;for(const key of ['customer_id','event_date','event_time','fulfillment','delivery_address'])draft[key]=data.get(key)||'';if(old!==draft.customer_id){const c=state.customers.find(c=>c.id===draft.customer_id);draft.delivery_address=L.address(c||{});}}else if(draft.step===2){draft.payment_method=data.get('payment_method');draft.pix_enabled=data.has('pix_enabled');draft.pix_percent=Number(data.get('pix_percent')||0);draft.discount_cents=L.amount(data.get('discount'));draft.delivery_cents=L.amount(data.get('delivery'));draft.notes=data.get('notes');draft.production_notes=data.get('production_notes');}saveDraft();}
function validateCustomer(){const c=state.customers.find(c=>c.id===draft.customer_id&&c.active);if(!c)throw Error('Selecione um cliente ativo.');if(!draft.event_date||draft.event_date<L.today()||!/^\d\d:\d\d$/.test(draft.event_time))throw Error('Informe uma data de hoje em diante e o horário.');if(draft.fulfillment==='Entrega'&&!draft.delivery_address.trim())throw Error('Preencha o endereço de entrega.');return c;}
function showModal(html){$('#modal-content').innerHTML=html;if(!modal.open)modal.showModal();}
function confirm(title,text,action){confirmAction=action;showModal(`<h2>${E(title)}</h2><p>${E(text)}</p><div class="toolbar">${button('Confirmar','confirm','','primary')}${button('Cancelar','close-modal')}</div>`);}
function selectedNav(id){const split=id.indexOf(':');return split<0?[id,'']:[id.slice(0,split),id.slice(split+1)];}
async function action(name,id){
 if(name==='nav'){if(route==='quote')collectQuote();const [next,selected]=selectedNav(id);go(next,selected);return;}
 if(name==='new-quote'){if(draft&&(draft.lines.length||draft.customer_id)){confirm('Começar outro orçamento?','Há um rascunho salvo. Confirme para substituí-lo por uma nova encomenda.',()=>{draft=newDraft(id);builder=null;editingLine=-1;saveDraft();go('quote');});}else{draft=newDraft(id);builder=null;editingLine=-1;saveDraft();go('quote');}return;}
 if(name==='demo'){mode=mode==='demo'?'real':'demo';builder=null;editingLine=-1;load();go('home');return;}
 if(name==='order-filter'){orderFilter=id;render();return;}
 if(name==='page'){page=Number(id);render();return;}
 if(name==='product-view'){const p=state.products.find(p=>p.id===id);showModal(`<h2>${E(p.name)}</h2>${p.photos.map(src=>image(src)).join('')}<p>${E(p.description)}</p>${p.composition.length?'<ul class="item-list">'+p.composition.map(c=>'<li>• '+E(c)+'</li>').join('')+'</ul>':''}<p><b>${L.money(L.price(p).value)} / ${E(p.unit)}</b></p><div class="toolbar">${button('Editar produto','modal-product',p.id)}${button('Fechar','close-modal')}</div>`);return;}
 if(name==='modal-product'){modal.close();go('product-edit',id);return;}
 if(name==='cancel-form'){if(modal.open){modal.close();formPhotos={};return;}go(route==='product-edit'?'products':route==='customer-edit'?'customers':route==='inventory-edit'?'inventory':'more');return;}
 if(name==='delete-customer'){const c=state.customers.find(c=>c.id===id),has=state.quotes.some(q=>q.customer_id===id);confirm(has?'Arquivar '+c.name+'?':'Excluir '+c.name+'?',has?'O cadastro sai da lista ativa. Seus pedidos e pagamentos anteriores serão preservados.':'O cliente será excluído. Esta ação não pode ser desfeita.',()=>{commit(s=>{if(has)s.customers.find(c=>c.id===id).active=false;else s.customers=s.customers.filter(c=>c.id!==id);});render();toast(has?'Cliente arquivado.':'Cliente excluído.');});return;}
 if(name==='restore-customer'){commit(s=>s.customers.find(c=>c.id===id).active=true);render();toast('Cliente restaurado.');return;}
 if(name==='close-modal'){modal.close();confirmAction=null;return;}
 if(name==='confirm'){const fn=confirmAction;confirmAction=null;modal.close();if(fn)await fn();return;}
 if(name==='inline-customer'){collectQuote();formPhotos.customer='';showModal('<h2>Novo cliente</h2>'+formShell('customer',customerFields()));return;}
 if(name==='quote-back'){collectQuote();draft.step=Math.max(0,draft.step-1);saveDraft();render();window.scrollTo(0,0);return;}
 if(name==='quote-step'){draft.step=Number(id);saveDraft();render();window.scrollTo(0,0);return;}
 if(name==='quote-next'){if(editingLine>=0)throw Error('Salve ou cancele a edição do item antes de continuar.');if(!draft.lines.length)throw Error('Adicione pelo menos um item ao pedido.');draft.step=2;saveDraft();render();window.scrollTo(0,0);return;}
 if(name==='edit-line'){editingLine=Number(id);const line=copy(draft.lines[editingLine]);builder={...line,exception:!!line.negotiation?.notes,negotiation:line.negotiation?.notes||''};formPhotos={};render();window.scrollTo(0,0);return;}
 if(name==='cancel-line'){builder=null;editingLine=-1;formPhotos={};render();return;}
 if(name==='remove-line'){const index=Number(id);confirm('Remover este item?','O restante do orçamento será mantido.',()=>{draft.lines.splice(index,1);editingLine=-1;builder=null;saveDraft();render();});return;}
 if(name==='save-quote'){const c=validateCustomer(),t=L.totals(draft.lines,draft);if(t.total_cents<=0)throw Error('O orçamento precisa ter valor maior que zero.');const old=state.quotes.find(q=>q.id===draft.id);if(old&&(old.payments.length||old.delivered))throw Error('Pedidos com pagamentos têm os valores preservados.');const q={...copy(draft),id:old?.id||uid(),number:old?.number||Math.max(0,...state.quotes.map(q=>q.number))+1,customer:copy(c),shop:{...copy(state.settings),logo:formPhotos.quoteLogo||draft.logo||state.settings.logo},created_at:old?.created_at||L.today(),valid_until:old?.valid_until||L.plusDays(L.today(),7),totals:t,payments:[],delivered:false};delete q.step;commit(s=>{if(old)s.quotes[s.quotes.findIndex(x=>x.id===q.id)]=q;else s.quotes.push(q);});draft=null;builder=null;saveDraft();go('orders');toast('Orçamento #'+String(q.number).padStart(4,'0')+' salvo. Abra Ver pedido quando precisar.');return;}
 if(name==='edit-order'){const q=state.quotes.find(q=>q.id===id);if(q.payments.length||q.delivered)throw Error('Este pedido possui recebimentos e tem os valores preservados.');draft={...copy(q),step:0};builder=null;editingLine=-1;saveDraft();go('quote');return;}
 if(name==='renew-order'){commit(s=>s.quotes.find(q=>q.id===id).valid_until=L.plusDays(L.today(),7));render();toast('Validade renovada por sete dias.');return;}
 if(name==='deliver-order'){const q=state.quotes.find(q=>q.id===id);if(L.paid(q)!==q.totals.total_cents)throw Error('Quite o saldo antes de concluir a entrega.');confirm('Concluir entrega / retirada?','Confirme que o cliente já recebeu a encomenda.',()=>{commit(s=>s.quotes.find(q=>q.id===id).delivered=true);render();toast('Entrega registrada.');});return;}
 if(name==='order-logo'){if(!formPhotos.orderLogo)throw Error('Envie uma logo antes de aplicar ao orçamento.');commit(s=>s.quotes.find(q=>q.id===id).shop.logo=formPhotos.orderLogo);render();toast('Logo atualizada. Valores e pagamentos preservados.');return;}
 if(name==='pdf'){const split=id.lastIndexOf(':'),q=state.quotes.find(q=>q.id===id.slice(0,split)),kind=id.slice(split+1);await window.DoceDocuments.generate(q,state,kind.startsWith('kitchen'),kind.includes('share'));return;}
 if(name==='agenda-day'){activeDay=id;render();return;}
 if(name==='remove-photo'){const [key,index]=id.split(':');if(key==='product')formPhotos.product.splice(Number(index),1);else formPhotos[key]='';const preview=$('#photos_'+key);if(preview)preview.innerHTML=photoPreview(key,key==='product');if(key==='itemReference'&&builder)builder.reference_photo='';if(key==='quoteLogo'&&draft){draft.logo='';saveDraft();}return;}
 if(name==='request-notifications'){if(window.Android)Android.requestNotifications();else throw Error('As notificações do celular são ativadas no APK Android.');return;}
 if(name==='notification-settings'){if(window.Android)Android.notificationSettings();return;}
 if(name==='test-email'){if(mode==='demo')throw Error('Use seus dados reais para testar o envio.');if(window.Android){Android.testReminderEmail();toast('Enviando e-mail de teste…');}else throw Error('Instale o APK Android para configurar o envio automático neste celular.');return;}
 if(name==='cep'){await lookupCep();return;}
 if(name==='backup'){const raw=JSON.stringify({format:'doce-atelie-android',created_at:new Date().toISOString(),state});if(window.Android)Android.exportBackup(raw);else download(new Blob([raw],{type:'application/json'}),'DoceAtelie-backup.json');return;}
 if(name==='import'){if(window.Android)Android.importBackup();else $('#backup-input').click();return;}
 if(name==='restore-point'){const text=window.Android?Android.restorePoint():localStorage.getItem('doce-restore-point-'+mode);if(!text||text==='null')throw Error('Não há cópia anterior à restauração neste aparelho.');window.receiveBackup(JSON.parse(text));return;}
}
function download(blob,name){const link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download=name;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(link.href),1000);}
async function submit(kind,form){const data=new FormData(form),values=Object.fromEntries(data);
 if(kind==='notifications'){
  if(mode==='demo')throw Error('Configure os alertas nos seus dados reais.');
  const settings=L.reminderSettings({...state.settings,reminders_enabled:data.has('reminders_enabled'),local_notifications:data.has('local_notifications'),alert_days:data.getAll('alert_days').map(Number),alert_time:values.alert_time,notification_email:values.notification_email.trim(),email_enabled:data.has('email_enabled'),smtp_host:values.smtp_host.trim(),smtp_port:Number(values.smtp_port),smtp_security:values.smtp_security,smtp_username:values.smtp_username.trim(),smtp_sender:values.smtp_sender.trim()});
  const status=window.Android?JSON.parse(Android.reminderStatus()):{};
  if(settings.reminders_enabled&&settings.email_enabled&&!values.smtp_password&&!status.has_password)throw Error('Cadastre a senha de aplicativo para ativar os e-mails automáticos.');
  if(values.smtp_password){if(!window.Android)throw Error('A senha é protegida no dispositivo. Configure o envio no APK Android.');const error=Android.saveMailPassword(values.smtp_password);if(error)throw Error(error);}
  commit(s=>s.settings=settings);go('notifications');if(settings.reminders_enabled&&settings.local_notifications&&window.Android&&!status.permission)Android.requestNotifications();toast('Alertas salvos. A senha não será incluída no backup.');return;
 }
 if(kind==='customer'){const inline=modal.open,id=inline?'':entity,old=state.customers.find(c=>c.id===id);const c=L.customer({...values,id:old?.id||uid(),photo:formPhotos.customer||'',active:old?.active??true});commit(s=>{if(old)s.customers[s.customers.findIndex(x=>x.id===old.id)]=c;else s.customers.push(c);});if(inline){modal.close();draft.customer_id=c.id;draft.delivery_address=L.address(c);saveDraft();render();}else go('customer-detail',c.id);toast('Cliente salvo.');return;}
 if(kind==='product'){const old=state.products.find(p=>p.id===entity),category=values.category,p={id:old?.id||uid(),name:values.name.trim(),category,description:values.description.trim(),composition:values.composition.split('\n').map(x=>x.trim()).filter(Boolean),unit:L.fillings[category]?'kg':category===L.categories[2]?'cento':'un',price_cents:L.amount(values.price),active:data.has('active'),promo_enabled:data.has('promo_enabled'),promo_cents:L.amount(values.promo),promo_start:values.promo_start,promo_end:values.promo_end,photos:[...(formPhotos.product||[])]};if(!p.name||!L.categories.includes(category))throw Error('Informe nome e categoria.');if(p.photos.length>3)throw Error('Mantenha até três fotos.');if(p.promo_enabled&&(!p.promo_start||!p.promo_end||p.promo_end<p.promo_start||p.promo_cents<=0||p.promo_cents>=p.price_cents))throw Error('Defina um período válido e um preço promocional positivo, menor que o normal.');commit(s=>{if(old)s.products[s.products.findIndex(x=>x.id===old.id)]=p;else s.products.push(p);});go('products');toast('Produto salvo. Pedidos antigos mantêm os valores registrados.');return;}
 if(kind==='inventory'){const old=state.inventory.find(i=>i.id===entity),i={id:old?.id||uid(),name:values.name.trim(),brand:values.brand.trim(),content:Number(values.content),content_unit:values.content_unit,stock:Number(values.stock),package_unit:values.package_unit,paid_cents:L.amount(values.paid),photo:formPhotos.inventory||''};if(!i.name||!Number.isFinite(i.content)||i.content<=0||!Number.isFinite(i.stock)||i.stock<0)throw Error('Confira o nome, o conteúdo e a quantidade em estoque.');commit(s=>{if(old)s.inventory[s.inventory.findIndex(x=>x.id===old.id)]=i;else s.inventory.push(i);});go('inventory');toast('Insumo salvo e custo calculado.');return;}
 if(kind==='settings'){const settings={...state.settings,name:values.name.trim(),phone:values.phone.trim(),document:values.document.trim(),address:values.address.trim(),change_days:Number(values.change_days),logo:formPhotos.logo||''};if(!settings.name||!Number.isInteger(settings.change_days)||settings.change_days<0||settings.change_days>365)throw Error('Informe o nome da loja e o prazo de alteração entre 0 e 365 dias.');commit(s=>s.settings=settings);go('more');toast('Nome e logo atualizados no sistema e nos próximos orçamentos.');return;}
 if(kind==='quote-client'){collectQuote();validateCustomer();draft.step=1;saveDraft();render();window.scrollTo(0,0);return;}
 if(kind==='line'){const product=collectBuilder(),line=L.line(product,builder);if(editingLine>=0)draft.lines[editingLine]=line;else draft.lines.push(line);editingLine=-1;saveDraft();render();toast('Item salvo no pedido.');return;}
 if(kind==='quote-payment'){collectQuote();validateCustomer();if(L.totals(draft.lines,draft).total_cents<=0)throw Error('O orçamento precisa ter valor maior que zero.');draft.step=3;formPhotos.quoteLogo=draft.logo||state.settings.logo;saveDraft();render();window.scrollTo(0,0);return;}
 if(kind==='payment'){if(!data.has('confirmed'))throw Error('Confirme que o valor já foi recebido antes de registrar.');const q=state.quotes.find(q=>q.id===entity),p=L.payment(q,L.amount(values.amount),values.method,(data.has('deposit')?'Sinal · ':'Pagamento · ')+(values.note||''));commit(s=>s.quotes.find(q=>q.id===entity).payments.push(p));render();toast('Recebimento registrado. Status e saldo atualizados.');return;}
}
document.addEventListener('click',event=>{const node=event.target.closest('[data-action]');if(!node)return;event.preventDefault();Promise.resolve(action(node.dataset.action,node.dataset.id||'')).catch(exc=>error(exc.message));});
document.addEventListener('submit',event=>{const form=event.target;if(!form.dataset.form)return;event.preventDefault();Promise.resolve(submit(form.dataset.form,form)).catch(exc=>error(exc.message,form));});
document.addEventListener('change',event=>{const node=event.target;try{
 if(node.dataset.photo){uploadPhoto(node).catch(exc=>error(exc.message));return;}
 if(node.id==='backup-input'){const file=node.files[0];if(file){if(file.size>45*1024*1024)throw Error('O backup deve ter até 45 MB.');file.text().then(text=>window.receiveBackup(JSON.parse(text))).catch(exc=>error('Backup inválido: '+exc.message));}node.value='';return;}
 if(node.name==='catalog_category'){productCategory=node.value;render();return;}
 if(node.name==='customer_filter'){customerFilter=node.value;page=1;render();return;}
 if(node.name==='agenda_month'){activeMonth=node.value;activeDay=activeMonth+'-01';render();return;}
 if(node.closest('#builder-form')){const previousKind=builder?.brigadeiro_type;collectBuilder();if(node.name==='builder_category'||node.name==='product_id'){const p=node.name==='product_id'?state.products.find(p=>p.id===node.value):state.products.find(p=>p.active&&p.category===node.value);builder={product_id:p.id,quantity:L.fillings[p.category]?2:1,fillings:[],extras:[],flavors:[],details:'',gift:false,reference_photo:''};formPhotos={};}else if(node.name==='brigadeiro_type'&&previousKind!==node.value)builder.flavors=[];const structural=['builder_category','product_id','brigadeiro_type','split','fillings','extras'];if(structural.includes(node.name)||/^extra_\d+_type$/.test(node.name))render();else if(node.name==='quantity'&&L.fillings[getBuilderProduct().category]){const heading=$('#filling-heading');if(heading)heading.textContent='Escolha até '+(builder.quantity<2?1:2)+' recheio(s)';const block=$('#cake-exception');const needed=builder.quantity<2||builder.fillings.length>(builder.quantity<2?1:2);if(block&&needed!==!!block.querySelector('input'))block.innerHTML=exceptionFields();}else for(const extra of builder.extras){const i=L.extras.indexOf(extra.name),p=$('#extra_total_'+i);if(p)p.textContent=extra.quantity+' × '+L.money(extra.unit_cents)+' = '+(extra.gift?'[BRINDE]':L.money(extra.quantity*extra.unit_cents));}return;}
 if(route==='quote'&&!modal.open){const old=draft.customer_id;collectQuote();if(node.name==='customer_id'&&old!==draft.customer_id||node.name==='payment_method'||node.name==='pix_enabled')render();}
 if(node.dataset.cep)lookupCep().catch(exc=>error(exc.message));
 }catch(exc){error(exc.message);}
});
document.addEventListener('input',event=>{const node=event.target;if(node.dataset.search){filter=node.value;const start=node.selectionStart;page=1;render();const input=app.querySelector('[data-search="'+node.dataset.search+'"]');input.focus();input.setSelectionRange(start,start);}else if(route==='quote'&&!modal.open&&draft?.step!==1){try{collectQuote();}catch(ignored){}}});
async function uploadPhoto(input){const file=input.files[0];if(!file)return;const key=input.dataset.photo;if(key==='product'&&(formPhotos.product||[]).length>=3)throw Error('Mantenha até três fotos por produto.');if(file.size>10*1024*1024)throw Error('A imagem deve ter até 10 MB.');if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw Error('Use imagem JPG, PNG ou WEBP.');const url=URL.createObjectURL(file);try{const picture=await new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=()=>reject(Error('Imagem inválida.'));img.src=url;});if(picture.naturalWidth*picture.naturalHeight>45000000)throw Error('Imagem com resolução muito alta. Use uma foto de até 45 megapixels.');const ratio=Math.min(1,900/picture.naturalWidth,900/picture.naturalHeight),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(picture.naturalWidth*ratio));canvas.height=Math.max(1,Math.round(picture.naturalHeight*ratio));const context=canvas.getContext('2d');context.fillStyle='#fff';context.fillRect(0,0,canvas.width,canvas.height);context.drawImage(picture,0,0,canvas.width,canvas.height);let src=canvas.toDataURL('image/jpeg',.78);if(src.length>850000)src=canvas.toDataURL('image/jpeg',.5);if(src.length>850000)throw Error('A imagem continua muito grande. Escolha uma foto menor.');const id=uid();commit(s=>s.images[id]=src);if(key==='product')formPhotos.product.push(id);else formPhotos[key]=id;const preview=$('#photos_'+key);if(preview)preview.innerHTML=photoPreview(key,key==='product');if(key==='itemReference'&&builder)builder.reference_photo=id;if(key==='quoteLogo'&&draft){draft.logo=id;saveDraft();}toast('Imagem adicionada.');}finally{URL.revokeObjectURL(url);input.value='';}}
async function lookupCep(){const input=document.querySelector('dialog[open] [name=postal_code]')||document.querySelector('[name=postal_code]');if(!input)return;const code=input.value.replace(/\D/g,'');if(!/^\d{8}$/.test(code))throw Error('Informe um CEP com oito dígitos.');const form=input.closest('form'),id=uid();postalRequests.set(id,{form,code});const hint=form.querySelector('#cep-message');hint.textContent='Buscando endereço…';if(window.Android)Android.lookupCep(code,id);else window.onPostalResult({id,error:'Na visualização de desenvolvimento, preencha manualmente. No APK, a consulta usa o ViaCEP.'});}
window.onPostalResult=payload=>{const request=postalRequests.get(payload.id);postalRequests.delete(payload.id);if(!request||!request.form.isConnected||request.form.elements.postal_code.value.replace(/\D/g,'')!==request.code)return;const hint=request.form.querySelector('#cep-message');if(payload.error){hint.textContent=payload.error;return;}for(const [source,dest] of [['logradouro','street'],['bairro','neighborhood'],['localidade','city'],['uf','state']])if(request.form.elements[dest])request.form.elements[dest].value=payload.result[source]||'';hint.textContent='Endereço localizado. Confira o número e o complemento.';};
window.onNativeNotice=text=>{toast(text);if(route==='notifications')render();};
window.openReminder=id=>{if(mode!=='real'){mode='real';load();}go(state.quotes.some(q=>q.id===id)?'order':'orders',id);};
window.receiveBackup=backup=>{try{if(backup.format!=='doce-atelie-android')throw Error('Selecione um backup do aplicativo Android.');const imported=L.validateBackup(backup.state);pendingBackup=copy(imported);confirm('Restaurar cópia de segurança?',`${imported.customers.length} cliente(s) e ${imported.quotes.length} pedido(s) serão restaurados. Os dados atuais deste modo serão substituídos. Uma cópia anterior ficará guardada neste aparelho.`,()=>{const previous=JSON.stringify({format:'doce-atelie-android',state});if(window.Android)Android.saveRestorePoint(previous);else localStorage.setItem('doce-restore-point-'+mode,previous);persist(pendingBackup);state=pendingBackup;pendingBackup=null;draft=null;builder=null;saveDraft();go('home');toast('Backup restaurado. Confira os cadastros e pedidos.');});}catch(exc){error(exc.message);}};
window.appBack=()=>{if(modal.open){modal.close();return true;}if(route==='quote'&&draft?.step>0){action('quote-back','');return true;}if(route!=='home'){go('home');return true;}return false;};
try{load();render();}catch(exc){app.innerHTML='<div id="fatal"><h1>Não foi possível abrir os dados</h1><p>'+E(exc.message)+'</p><p>Preserve o aplicativo e o backup antes de reinstalar.</p></div>';}
